// La sortie du Redacteur repasse le schema, puis la garde anti-fabrication (aucun chiffre, aucun prix, aucun nom d'editeur).
const g = $('Revalider la qualification').item.json;
const r = ($input.first().json.output) || {};
const t = String(r.texte || '');
const bas = t.toLowerCase();
const INTERDITS = ['€', 'euro', 'tva', 'ttc', 'presti'];
if (typeof r.texte !== 'string' || t.trim().length < 1 || t.length > 1200 || t.split('').some((c) => c >= '0' && c <= '9') || INTERDITS.some((x) => bas.indexOf(x) >= 0)) throw new Error('proposition refusée : chiffre, prix ou nom d’éditeur');
return [{ json: Object.assign({}, g, { proposition_modele: { canal: 'email', objet: String(r.objet || 'Votre demande').slice(0, 120), texte: t, outil: 'valider_reponse_proposee' } }) }];

// Gabarit Accueil, reponse : l'enveloppe presti-dep-accueil@1. Rien n'est decide ici (le tri et les decisions restent ceux du chef).
const items = $input.all();
const premier = items[0].json;
const cfg = premier.config;
const CANAL = { email: 'email', gmail: 'email', outlook: 'email', imap: 'email', plateforme_devis: 'email', facebook_lead: 'email', telegram: 'telegram' };
const maintenant = new Date().toISOString();
const demandes = items.map((it) => {
  const j = it.json;
  const d = Object.assign({}, j.demande);
  d.canal = CANAL[j.canal_origine] || 'page_p';
  d.champs = Object.assign({}, d.champs, { canal: String(j.canal_origine).slice(0, 30) });
  d.proposition = j.proposition_modele || d.proposition || null;
  return d;
});
return [{ json: { contrat: 'presti-dep-accueil@1', organisation_id: premier.organisation_id, simulation: premier.simulation, cle_idempotence: 'dep:accueil:' + premier.organisation_id + ':' + maintenant.slice(0, 16), trace: { execution_parent: 'gabarit-artisan-accueil-reponse', declencheur: 'cadence', tentative: 0 }, config: { nom_artisan: cfg.marque_artisan, offre: cfg.offre, mode_reponse: cfg.mode_reponse, capacites: cfg.capacites, pilote: cfg.pilote, parties_depuis_24h: cfg.parties_depuis_24h, interrupteur_general: cfg.interrupteur_general !== false, interrupteur_departement: cfg.interrupteur_departement !== false, mots_escalade_artisan: cfg.mots_escalade_artisan || [], fournisseurs: cfg.fournisseurs || [], horaires: cfg.horaires, plafond_jour: cfg.plafond_jour, qualification: cfg.qualification }, donnees: { demandes: demandes, empreintes_connues: cfg.empreintes_connues || [], cles_existantes: cfg.cles_existantes || [], maintenant: maintenant } } }];

// Gabarit Accueil, reponse : traduit la sortie du chef en voies d'ecriture. Ne decide de rien (la decision est celle de presti-dep-accueil).
const s = $input.first().json || {};
const env = $('Préparer la demande au chef').first().json;
const org = env.organisation_id;
const sim = env.simulation;
const cap = env.config.capacites || [];
const autonome = cap.indexOf('plateforme.ia.auto') >= 0 && cap.indexOf('assistant.pilote') >= 0;
const pilotePermis = autonome && env.config.mode_reponse === 'auto' && !!(env.config.pilote && env.config.pilote.actif);
const groupes = new Map($('Regrouper par conversation').all().map((it) => [it.json.demande.id, it.json]));
if (s.statut !== 'ok') return [{ json: { voie: 'rien', organisation_id: org, simulation: sim, statut: s.statut || 'sans_statut' } }];
const sortie = [];
for (const e of s.effets_prevus || []) {
  if (e.effet === 'ecrire_carte') {
    sortie.push({ json: { voie: 'carte', organisation_id: org, simulation: sim, corps: e.corps } });
    const g = groupes.get(e.corps.objet_id);
    if (!autonome && g && e.corps.brouillon && e.corps.type_action === 'reponse_prospect' && ['gmail', 'outlook'].indexOf(g.canal_origine) >= 0) {
      sortie.push({ json: { voie: 'brouillon', organisation_id: org, simulation: sim, canal_origine: g.canal_origine, conversation_cle: g.conversation_cle, fil_externe: g.fil_externe, id_boite: g.id_boite, objet: e.corps.brouillon.objet, texte: e.corps.brouillon.texte, marque_artisan: env.config.nom_artisan } });
    }
  } else if (e.effet === 'mettre_en_file_pilote') {
    const g = groupes.get(e.corps.objet_id);
    if (pilotePermis) sortie.push({ json: { voie: 'pilote', organisation_id: org, simulation: sim, corps: e.corps, envoi_par: g ? g.canal_origine : null } });
    else sortie.push({ json: { voie: 'refus_offre', organisation_id: org, simulation: sim, cle: e.corps.cle } });
  }
}
if (Array.isArray(s.journal) && s.journal.length) sortie.push({ json: { voie: 'journal', organisation_id: org, simulation: sim, lignes: s.journal } });
return sortie;

// Simulation : rien n'est ecrit ni envoye ; les effets prevus sont listes. Studio n'envoie jamais.
const prevus = [];
for (const it of $input.all()) {
  const j = it.json;
  if (j.voie === 'carte') prevus.push({ effet: 'ecrire_carte', cle: j.corps && j.corps.cle });
  else if (j.voie === 'pilote') prevus.push({ effet: 'mettre_en_file_pilote', cle: j.corps && j.corps.cle, envoi_par: j.envoi_par, envoi_fait_par: 'gabarit-artisan-accueil-envoi' });
  else if (j.voie === 'brouillon') prevus.push({ effet: 'brouillon_' + j.canal_origine, conversation_cle: j.conversation_cle });
  else if (j.voie === 'journal') prevus.push({ effet: 'inserer_journal', lignes: (j.lignes || []).length });
  else prevus.push({ effet: 'aucun', voie: j.voie });
}
return [{ json: { simulation: true, effets_prevus: prevus, effets_faits: [] } }];

